# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
  }
}

# -----------------------------------------------------------------------------
# Route Configuration Templates
# -----------------------------------------------------------------------------

locals {
  # Internal route (websecure with TLS)
  internal_route = var.internal_domain != "" ? {
    rule        = "Host(`${var.internal_domain}`)"
    entryPoints = var.internal_entrypoint
    service     = var.app_name
    tls = {
      certResolver = var.cert_resolver
    }
    middlewares = var.internal_middlewares
  } : null

  # Public route (web HTTP - Cloudflare Flexible SSL forwards HTTP to origin)
  public_route = var.public_domain != "" ? {
    rule        = "Host(`${var.public_domain}`)"
    entryPoints = var.public_entrypoint
    service     = var.app_name
    middlewares = var.public_middlewares
  } : null

  # Service configuration
  service_config = {
    loadBalancer = merge(
      {
        servers = [
          { url = var.backend_url }
        ]
      },
      var.health_check != null ? { healthCheck = var.health_check } : {}
    )
  }

  # Complete Traefik config
  traefik_config = {
    http = {
      routers = merge(
        local.internal_route != null ? { "${var.app_name}" = local.internal_route } : {},
        local.public_route != null ? { "${var.app_name}-public" = local.public_route } : {}
      )
      services = {
        "${var.app_name}" = local.service_config
      }
    }
  }

  # YAML output
  config_yaml = yamlencode(local.traefik_config)

  # Target path on Traefik LXC
  remote_config_path = "/config/dynamic/${var.app_name}.yml"
}

# -----------------------------------------------------------------------------
# Write Config to Temporary File
# -----------------------------------------------------------------------------

resource "local_file" "route_config" {
  content  = local.config_yaml
  filename = "${path.module}/.tmp/${var.app_name}.yml"

  # Create directory if needed
  provisioner "local-exec" {
    command = "mkdir -p ${path.module}/.tmp"
    when    = create
  }
}

# -----------------------------------------------------------------------------
# Sync to Traefik LXC using filesync provider
# -----------------------------------------------------------------------------

resource "filesync_file" "traefik_route" {
  source      = local_file.route_config.filename
  destination = local.remote_config_path
  host        = var.traefik_host

  # SSH configuration
  ssh_key_path = var.ssh_private_key_path

  # File permissions
  owner = "root"
  group = "root"
  mode  = "0644"

  depends_on = [local_file.route_config]
}

# -----------------------------------------------------------------------------
# Reload Traefik Configuration via Ansible
# -----------------------------------------------------------------------------
# Sends SIGUSR1 to Traefik process for graceful config reload (no restart)

resource "ansible_navigator_run" "reload_traefik" {
  count = var.reload_traefik ? 1 : 0

  depends_on = [filesync_file.traefik_route]

  triggers = {
    config_hash = local_file.route_config.content
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.ssh_private_key_path)
    }]
  }

  playbook = <<-EOT
    - name: Reload Traefik configuration
      hosts: traefik
      gather_facts: no
      vars:
        app_name: ${var.app_name}

      tasks:
        # =====================================================================
        # Graceful Reload - SIGUSR1 triggers config reload without restart
        # =====================================================================
        - name: Send SIGUSR1 to Traefik for config reload
          ansible.builtin.command:
            cmd: docker exec traefik kill -USR1 1
          register: reload_result
          failed_when: reload_result.rc != 0
          changed_when: true

        - name: Display reload status
          ansible.builtin.debug:
            msg: "Traefik configuration reloaded for {{ app_name }}"
  EOT

  inventory = yamlencode({
    traefik = {
      hosts = {
        traefik = {
          ansible_host = var.traefik_host
          ansible_user = "root"
        }
      }
    }
  })
}

# -----------------------------------------------------------------------------
# Cleanup Temp File
# -----------------------------------------------------------------------------
# Note: Temp files are left in .tmp/ directory for debugging
# They can be safely deleted manually or via .gitignore

# =============================================================================
# LXC Sidecars Module Variables
# =============================================================================
# This module manages sidecar services for LXC containers:
#   - Backup (proxmox-backup-client with PBS)
#   - Alloy (Grafana Alloy for log/metric collection)
#   - DIUN (Docker image update notifications) - Future
# =============================================================================

# =============================================================================
# Container Information
# =============================================================================

variable "container_id" {
  description = "LXC container ID"
  type        = number
}

variable "container_ip" {
  description = "Container IP address (without CIDR)"
  type        = string
}

variable "container_name" {
  description = "Container hostname"
  type        = string
}

# =============================================================================
# Proxmox SSH Connection (for Ansible deployment)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address"
  type        = string
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
}

# =============================================================================
# Backup Configuration
# =============================================================================

variable "backup" {
  description = "Backup configuration for PBS client"
  type = object({
    enabled     = bool
    schedule    = string                    # "daily", "02:00", "Sun 03:00"
    retention   = optional(string, "7")     # Keep N backups
    namespace   = string                    # PBS namespace (usually container name)

    # Pre-backup commands (database dumps, etc.)
    pre_backup_commands = optional(list(object({
      name    = string
      command = string
      timeout = optional(number, 300)
    })), [])

    # Paths to backup/exclude
    include_paths = optional(list(string), ["/config"])
    exclude_paths = optional(list(string), ["/var/lib/docker/overlay2"])

    # PBS server settings
    pbs_server     = optional(string, "10.100.1.102")
    pbs_datastore  = optional(string, "homelab")
    pbs_user       = optional(string, "backup@pbs")
    pbs_password_cmd = optional(string, "op read 'op://homelab/PBS - Proxmox Backup Server/password'")

    # Alert settings
    ntfy_url      = optional(string, "http://10.100.5.100:8080/homelab-alerts")
    ntfy_priority = optional(string, "default")
    ntfy_tags     = optional(string, "backup")
  })
  default = null

  validation {
    condition = var.backup == null || (
      var.backup.enabled == true && var.backup.namespace != ""
    )
    error_message = "If backup is enabled, namespace must be provided."
  }

  validation {
    condition = var.backup == null || (
      var.backup.schedule == "daily" ||
      can(regex("^[0-9]{2}:[0-9]{2}$", var.backup.schedule)) ||
      can(regex("^(mon|tue|wed|thu|fri|sat|sun) [0-9]{2}:[0-9]{2}$", lower(var.backup.schedule)))
    )
    error_message = "Schedule must be 'daily', 'HH:MM', or 'day HH:MM' (e.g., 'Sun 03:00')."
  }
}

# =============================================================================
# Container Management Agents
# =============================================================================

variable "pulse_agent" {
  description = "Pulse Docker agent configuration for container monitoring"
  type = object({
    enabled     = optional(bool, false)
    pulse_url   = optional(string, "http://10.100.1.104:7655")
    pulse_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.pulse_agent.enabled, false) == false || try(var.pulse_agent.pulse_token, "") != ""
    error_message = "If pulse_agent is enabled, pulse_token must be provided."
  }
}

variable "arcane_agent" {
  description = "Arcane remote agent configuration for container management"
  type = object({
    enabled         = optional(bool, false)
    manager_url     = optional(string, "http://10.100.1.104:3552")
    bootstrap_token = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.arcane_agent.enabled, false) == false || try(var.arcane_agent.bootstrap_token, "") != ""
    error_message = "If arcane_agent is enabled, bootstrap_token must be provided."
  }
}

# =============================================================================
# Grafana Alloy Agent
# =============================================================================

variable "alloy_agent" {
  description = "Grafana Alloy agent for log/metric collection to Loki/Prometheus"
  type = object({
    enabled        = optional(bool, false)
    loki_url       = optional(string, "https://loki-push.homelab.rambtech.dev")
    prometheus_url = optional(string, "https://prometheus-push.homelab.rambtech.dev")
    username       = optional(string, "")
    password       = optional(string, "")
  })
  default = {}

  validation {
    condition = try(var.alloy_agent.enabled, false) == false || (
      try(var.alloy_agent.username, "") != "" && try(var.alloy_agent.password, "") != ""
    )
    error_message = "If alloy_agent is enabled, username and password must be provided for authentication."
  }
}

# =============================================================================
# Future Sidecars (Placeholder)
# =============================================================================

variable "diun_enabled" {
  description = "Enable DIUN for Docker image update notifications"
  type        = bool
  default     = false
}

